```latex
\documentclass{hebrew-academic-template}
% Set custom margins (no need to \usepackage{geometry})
\geometry{top=8mm, bottom=6mm, left=12mm, right=12mm}
\begin{document}
% Custom-layout content (invoices, forms, etc.)
\end{document}
```

For book-length documents:
```latex
\hebrewchapter{שם הפרק}
\hebrewsection{סעיף בפרק: \entoc{Section}}
```

Verify your template version:
```latex
\documentclass{hebrew-academic-template}
\begin{document}
Version: \clsversion
\end{document}
```

Use the full chapter hierarchy:
```latex
\hebrewchapter{Introduction}
\hebrewsection{Background: \entoc{Background}}
```

```latex
\hebrewtitle{מחקר בשנת 2023 על AI}
```

```latex
\date{September 2025}
```

```latex
\hebrewsection{פרק 1: מבוא ל-Machine Learning}
```

```latex
\begin{enumerate}
    \item שלב 1: הכנת נתונים
    \item שלב 2: אימון מודל ML
\end{enumerate}
```

```latex
\begin{enumerate}
    \item שלב \num{1}: הכנת נתונים
    \item שלב \num{2}: אימון מודל \en{ML}
\end{enumerate}
```
**Rule:** All numbers in `\num{}`, English terms in `\en{}`
---

```latex
\begin{itemize}
    \item דיוק: 95.2%
    \item מהירות: 1000 מילים/שנייה
\end{itemize}
```

